package aoc.fovvox.day10;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import aoc.fovvox.Util;

public class Machine {
    private final String initialString;
    private String targetState;
    private List<Action> actions;
    private List<Integer> targetJoltage;

    public static Machine parse(final String string) {
        final String[] parts = string.split(" ");
        final String targetState = parts[0].replaceAll("\\[|\\]", "");
        final List<Action> actions = new ArrayList<>();
        for (int i = 1; i < parts.length - 1 ; i++) {
            final String part = parts[i].replaceAll("\\(|\\)","");
            final List<Integer> toggles = Arrays.stream(part.split(",")).map(Integer::parseInt).toList();
            actions.add(new Action(toggles));
        }
        final String joltageString = parts[parts.length -1 ].replaceAll("\\{|\\}", "");
        final List<Integer> joltage = new ArrayList<>(Arrays.stream(joltageString.split(",")).map(Integer::parseInt).toList());
        return new Machine(targetState, actions, joltage, string);
    }

    private Machine(final String targetState, final List<Action> actions, final List<Integer> joltage, final String initialString) {
        this.targetState = targetState;
        this.actions = actions;
        this.targetJoltage = joltage;
        this.initialString = initialString;
    }

    public int enable() {
        List<String> states = List.of(".".repeat(targetState.length()));
        List<String> nextStates = new ArrayList<>();
        int steps = 1;

        while (true) {
            for (final String state : states) {
                for (final Action action : actions) {
                    final String newState = action.apply(state);
                    if (targetState.equals(newState)) {
                        return steps;
                    }
                    nextStates.add(newState);
                }
            }
            states = nextStates;
            nextStates = new ArrayList<>();
            steps++;
        }
    }

    public int configureJoltage() {
        final List<Integer> startState =new ArrayList<>();
        for (var _ : targetJoltage) {
            startState.add(0);
        }
        List<List<Integer>> states = List.of(startState);
        List<List<Integer>> nextStates = new ArrayList<>();
        int steps = 1;
        while (true) {
            System.out.println("Step: " + steps + ", states: " + states.size());
            for (final List<Integer> state : states) {
                for (final Action action : actions) {
                    final List<Integer> newState = action.applyJoltage(state);
                    if (Util.equalsList(targetJoltage, newState)) {
                        return steps;
                    }
                    nextStates.add(newState);
                }
            }
            states = nextStates;
            nextStates = new ArrayList<>();
            steps++;
        }
    }

    public String getTargetState() {
        return targetState;
    }

    public void setTargetState(final String targetState) {
        this.targetState = targetState;
    }

    public List<Action> getActions() {
        return actions;
    }

    public void setActions(final List<Action> actions) {
        this.actions = actions;
    }

    public List<Integer> getTargetJoltage() {
        return targetJoltage;
    }

    public void setTargetJoltage(final List<Integer> targetJoltage) {
        this.targetJoltage = targetJoltage;
    }

    @Override
    public String toString() {
        return initialString;
    }

    private static class Action {
        List<Integer> toggles;

        public Action(final List<Integer> toggles) {
            this.toggles = toggles;
        }

        public String apply(final String state) {
            final char[] lamps = state.toCharArray();
            for (final Integer toggle : toggles) {
                if (lamps[toggle] == '#') {
                    lamps[toggle] = '.';
                } else {
                    lamps[toggle] = '#';
                }
            }
            return new String(lamps);
        }

        public List<Integer> applyJoltage(final List<Integer> joltage) {
            final List<Integer> newJoltage = new ArrayList<>(List.copyOf(joltage));
            for (final Integer toggle : toggles) {
                newJoltage.set(toggle, newJoltage.get(toggle)+1);
            }
            return newJoltage;
        }

        public List<Integer> getToggles() {
            return toggles;
        }

        public void setToggles(final List<Integer> toggles) {
            this.toggles = toggles;
        }
    }
}

package aoc.fovvox.day10;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import aoc.fovvox.Util;

public class Machine {
    private final String initialString;
    private String targetState;
    private List<Action> actions;
    private List<Integer> targetJoltage;

    public static Machine parse(final String string) {
        final String[] parts = string.split(" ");
        final String targetState = parts[0].replaceAll("\\[|\\]", "");
        final List<Action> actions = new ArrayList<>();
        for (int i = 1; i < parts.length - 1 ; i++) {
            final String part = parts[i].replaceAll("\\(|\\)","");
            final List<Integer> toggles = Arrays.stream(part.split(",")).map(Integer::parseInt).toList();
            actions.add(new Action(toggles));
        }
        final String joltageString = parts[parts.length -1 ].replaceAll("\\{|\\}", "");
        final List<Integer> joltage = new ArrayList<>(Arrays.stream(joltageString.split(",")).map(Integer::parseInt).toList());
        return new Machine(targetState, actions, joltage, string);
    }

    private Machine(final String targetState, final List<Action> actions, final List<Integer> joltage, final String initialString) {
        this.targetState = targetState;
        this.actions = actions;
        this.targetJoltage = joltage;
        this.initialString = initialString;
    }

    public int enable() {
        List<String> states = List.of(".".repeat(targetState.length()));
        List<String> nextStates = new ArrayList<>();
        int steps = 1;

        while (true) {
            for (final String state : states) {
                for (final Action action : actions) {
                    final String newState = action.apply(state);
                    if (targetState.equals(newState)) {
                        return steps;
                    }
                    nextStates.add(newState);
                }
            }
            states = nextStates;
            nextStates = new ArrayList<>();
            steps++;
        }
    }

    /**
     * Finds the minimum number of action applications that make the joltage counters
     * match the target exactly.
     * <p>
     * Actions only add to their counters and order does not matter, so this is not a
     * shortest-path search over reachable states. It is a search for non-negative
     * integer counts x_i (one per action) such that the sum of the chosen actions'
     * contributions equals the target, minimizing the sum of all x_i.
     * <p>
     * The search branches over actions (a small, fixed list), not over time steps or
     * reachable joltage vectors (which can be huge). This keeps memory use proportional
     * to the number of actions instead of exploding exponentially.
     */
    public int configureJoltage() {
        final int coordinateCount = targetJoltage.size();
        final int actionCount = actions.size();
        final int[] remaining = targetJoltage.stream().mapToInt(Integer::intValue).toArray();

        final int[][] covers = new int[actionCount][];
        for (int i = 0; i < actionCount; i++) {
            covers[i] = actions.get(i).getToggles().stream().mapToInt(Integer::intValue).toArray();
        }

        // suffixCovered[i][j] is true when some action with index >= i touches coordinate j.
        // Used to prune branches where a coordinate can no longer be reached.
        final boolean[][] suffixCovered = new boolean[actionCount + 1][coordinateCount];
        for (int i = actionCount - 1; i >= 0; i--) {
            System.arraycopy(suffixCovered[i + 1], 0, suffixCovered[i], 0, coordinateCount);
            for (final int j : covers[i]) {
                suffixCovered[i][j] = true;
            }
        }

        bestJoltageSteps = Integer.MAX_VALUE;
        searchJoltage(0, remaining, 0, covers, suffixCovered);
        return bestJoltageSteps;
    }

    private int bestJoltageSteps;

    private void searchJoltage(final int actionIndex, final int[] remaining, final int usedSoFar,
                                final int[][] covers, final boolean[][] suffixCovered) {
        if (usedSoFar >= bestJoltageSteps) {
            return; // no improvement possible from here, stop this branch
        }
        if (actionIndex == covers.length) {
            for (final int r : remaining) {
                if (r != 0) {
                    return; // leaf does not match the target, dead end
                }
            }
            bestJoltageSteps = usedSoFar;
            return;
        }
        for (int j = 0; j < remaining.length; j++) {
            if (remaining[j] > 0 && !suffixCovered[actionIndex][j]) {
                return; // coordinate j can never be reached by the actions left, dead end
            }
        }

        int maxCount = bestJoltageSteps - usedSoFar - 1;
        for (final int j : covers[actionIndex]) {
            maxCount = Math.min(maxCount, remaining[j]);
        }
        if (covers[actionIndex].length == 0) {
            maxCount = 0;
        }

        for (int count = maxCount; count >= 0; count--) {
            for (final int j : covers[actionIndex]) {
                remaining[j] -= count;
            }
            searchJoltage(actionIndex + 1, remaining, usedSoFar + count, covers, suffixCovered);
            for (final int j : covers[actionIndex]) {
                remaining[j] += count;
            }
        }
    }

    public String getTargetState() {
        return targetState;
    }

    public void setTargetState(final String targetState) {
        this.targetState = targetState;
    }

    public List<Action> getActions() {
        return actions;
    }

    public void setActions(final List<Action> actions) {
        this.actions = actions;
    }

    public List<Integer> getTargetJoltage() {
        return targetJoltage;
    }

    public void setTargetJoltage(final List<Integer> targetJoltage) {
        this.targetJoltage = targetJoltage;
    }

    @Override
    public String toString() {
        return initialString;
    }

    private static class Action {
        List<Integer> toggles;

        public Action(final List<Integer> toggles) {
            this.toggles = toggles;
        }

        public String apply(final String state) {
            final char[] lamps = state.toCharArray();
            for (final Integer toggle : toggles) {
                if (lamps[toggle] == '#') {
                    lamps[toggle] = '.';
                } else {
                    lamps[toggle] = '#';
                }
            }
            return new String(lamps);
        }

        public List<Integer> applyJoltage(final List<Integer> joltage) {
            final List<Integer> newJoltage = new ArrayList<>(List.copyOf(joltage));
            for (final Integer toggle : toggles) {
                newJoltage.set(toggle, newJoltage.get(toggle)+1);
            }
            return newJoltage;
        }

        public List<Integer> getToggles() {
            return toggles;
        }

        public void setToggles(final List<Integer> toggles) {
            this.toggles = toggles;
        }
    }
}
